/* =============================================================================
 * BUILD PROMPT - POVO AI Guidance, Compliance Check v1
 *
 * Contract (docs/ARCHITECTURE.md section 6):
 *   request  {request_id, category, point_text, participant_role, note,
 *             rule_findings:[{rule_id, title, severity}], allowed_rule_ids:[...14]}
 *   response {ok:true, issues:[{rule_id, excerpt, why}], suggested_text}
 *            | {ok:false, reason}
 *
 * The deterministic regex rules in the backend are the guaranteed floor. This
 * is the second pass: the model looks for ADDITIONAL issues only and drafts a
 * compliant rewrite. It never replaces or overrules a rule finding.
 * ========================================================================== */
const body = ($input.first().json || {}).body || {};
const reject = (reason) => [{ json: { valid: false, reason: String(reason).slice(0, 200) } }];
const str = (v) => (v === null || v === undefined ? '' : String(v)).replace(/\s+/g, ' ').trim();

/* The 14 compliance rules (docs/POC_FUNCTIONAL_SPEC.md section 6). */
const RULES = [
  { id: 'off',    chip: 'Off-label',      severity: 'high', title: 'Off-label or unapproved use', look: 'uses, doses, populations or indications other than moderate-to-severe HS in adults; unapproved dosing' },
  { id: 'claim',  chip: 'Claim',          severity: 'med',  title: 'Unbalanced or comparative claim', look: 'superlatives, "best", "safest", "better than", guarantees, head-to-head comparisons, efficacy without balance' },
  { id: 'ae',     chip: 'Adverse event',  severity: 'high', title: 'Possible adverse event (report to Pharmacovigilance within 24 h)', look: 'a patient who had a side effect, reaction, infection, lab abnormality, hospitalization or other harm while on a product' },
  { id: 'phi',    chip: 'Patient ID',     severity: 'high', title: 'Patient identifier', look: 'patient names or initials, dates of birth, ages with dates, record numbers, phone numbers, emails, addresses' },
  { id: 'vulgar', chip: 'Vulgar',         severity: 'high', title: 'Vulgar language', look: 'profanity or crude wording, including masked profanity' },
  { id: 'lang',   chip: 'Unprofessional', severity: 'med',  title: 'Unprofessional wording', look: 'insults, sarcasm, slang, disparaging remarks about the HCP, office or competitors' },
  { id: 'price',  chip: 'Pricing',        severity: 'med',  title: 'Pricing, samples or incentives', look: 'prices, discounts, coupons, copay amounts, free product, gifts, meals or other incentives' },
  { id: 'sens',   chip: 'Personal',       severity: 'med',  title: 'Sensitive or personal information', look: 'personal life details about the HCP or staff: health, family, religion, politics, finances' },
  { id: 'irr',    chip: 'Off topic',      severity: 'low',  title: 'Information unrelated to the call', look: 'content unrelated to HS care, POVO or the call, such as sports, weather or travel chat' },
  { id: 'fill',   chip: 'Filler',         severity: 'low',  title: 'Filler wording', look: 'filler such as "basically", "just", "you know", "kind of", "etc."' },
  { id: 'gib',    chip: 'Not readable',   severity: 'high', title: 'Text is not readable', look: 'keyboard mashing, random characters, text with no readable words' },
  { id: 'vague',  chip: 'Too vague',      severity: 'med',  title: 'Note is too vague (< 3 words or a generic phrase)', look: 'fewer than 3 words or a generic phrase such as "good call" or "discussed"' },
  { id: 'ph',     chip: 'Incomplete',     severity: 'med',  title: 'Note is incomplete (unfilled [brackets])', look: 'unfilled square-bracket placeholders' },
  { id: 'rel',    chip: 'Unrelated',      severity: 'med',  title: 'Not related to this point', look: 'a note that says nothing about the talking point it is attached to, or about HS or POVO' },
];
const RULE_BY_ID = new Map(RULES.map((r) => [r.id, r]));

const requestId = str(body.request_id);
if (!requestId) return reject('missing request_id');
const category = str(body.category).toLowerCase().replace(/s$/, '');
if (!category) return reject('missing category');
const note = String(body.note === null || body.note === undefined ? '' : body.note).trim();
if (!note) return reject('empty note');

const allowed = (Array.isArray(body.allowed_rule_ids) ? body.allowed_rule_ids : []).map(str).filter(Boolean);
if (!allowed.length) return reject('missing allowed_rule_ids');
const allowedKnown = allowed.filter((id) => RULE_BY_ID.has(id));
if (!allowedKnown.length) return reject('allowed_rule_ids has no known rule id');

const findings = (Array.isArray(body.rule_findings) ? body.rule_findings : [])
  .filter((f) => f && str(f.rule_id))
  .map((f) => ({ rule_id: str(f.rule_id), title: str(f.title) || (RULE_BY_ID.get(str(f.rule_id)) || {}).title || '', severity: str(f.severity) }));

// 200 characters for a point note, 600 for the "Additional notes" textarea.
const limit = category === 'additional' ? 600 : 200;

const SYSTEM_PROMPT = [
  'You are a pharmaceutical field-sales compliance reviewer for POVO AI Guidance at Incyte.',
  'POVO is an oral selective JAK1 inhibitor approved for moderate-to-severe hidradenitis suppurativa (HS) in adults.',
  'A POVO Sales Representative wrote the NOTE below after a call. Deterministic rules have already checked it; what they found is listed under RULE FINDINGS.',
  '',
  'YOUR TASK',
  '1. Find ADDITIONAL compliance issues that the rules missed. Only use rule ids from ALLOWED RULES. Never repeat a rule id that is already in RULE FINDINGS. If there is nothing more to add, return an empty issues array.',
  '   For each issue give rule_id, excerpt (copied character for character from the NOTE, at most 120 characters) and why (one short sentence).',
  '2. Write suggested_text: a compliant rewrite of the whole NOTE, at most ' + limit + ' characters, that fixes every rule finding and every issue you added.',
  '',
  'REWRITE RULES',
  "- Keep the rep's own facts: what was discussed, how the participant responded and the agreed next step. Do not add facts, outcomes, commitments or dates that are not in the NOTE.",
  '- Remove off-label details, adverse-event details, patient identifiers (names, initials, dates of birth, record numbers, phone numbers, emails, addresses), pricing, samples and incentives, vulgar or unprofessional wording, personal information, off-topic content and filler.',
  '- If an off-label use or question came up, write exactly: Off-label question sent to Medical Information',
  '- If a possible adverse event or other safety information came up, write exactly: Safety information reported to Pharmacovigilance',
  '- If pricing, cost, coverage or access came up, write exactly: Access questions referred to IncyteCARES',
  '- Never invent clinical claims. Do not add efficacy or safety statements, numbers, comparisons or trial results.',
  '- The POINT is approved (MLR) text and is context only. Never alter, quote at length or re-word it.',
  '- If nothing usable is left, write a short template the rep can complete, with square-bracket placeholders such as [how the participant responded] and [agreed next step].',
  '- If RULE FINDINGS is empty and you found no issue, return the NOTE unchanged as suggested_text.',
  '- Tone: a short, factual CRM call note in the past tense, professional US English. No emojis, no markdown.',
  '',
  'OUTPUT',
  'Return JSON only, with no prose and no code fences. Fields:',
  '- issues: array of objects with the fields rule_id, excerpt and why.',
  '- suggested_text: string.',
].join('\n');

const ruleTable = allowedKnown
  .map((id) => { const r = RULE_BY_ID.get(id); return '- ' + r.id + ' | ' + r.title + ' | severity ' + r.severity + ' | look for: ' + r.look; })
  .join('\n');
const findingBlock = findings.length
  ? findings.map((f) => '- ' + f.rule_id + ' | ' + f.title + (f.severity ? ' | ' + f.severity : '')).join('\n')
  : '- none';

const USER_PROMPT = [
  'CATEGORY: ' + category,
  'PARTICIPANT ROLE: ' + (str(body.participant_role) || 'HCP'),
  'SUGGESTED TEXT LIMIT: ' + limit + ' characters',
  '',
  'POINT (approved text, context only)',
  str(body.point_text) || '(none: free-text additional notes)',
  '',
  'ALLOWED RULES (id | title | severity | what to look for)',
  ruleTable,
  '',
  'RULE FINDINGS (already found by the deterministic rules)',
  findingBlock,
  '',
  'NOTE',
  note,
  '',
  'Return the JSON now.',
].join('\n');

return [{
  json: {
    valid: true,
    request_id: requestId,
    category,
    limit,
    note,
    allowed_rule_ids: allowed,
    finding_rule_ids: findings.map((f) => f.rule_id),
    system_prompt: SYSTEM_PROMPT.replace(/[{}]/g, ''),
    user_prompt: USER_PROMPT,
  },
}];

/* =============================================================================
 * GUARD - POVO AI Guidance, Compliance Check v1
 *
 * Response is exactly one of:
 *   {ok:true,  issues:[{rule_id, excerpt, why}], suggested_text}
 *   {ok:false, reason}
 *
 * Hard failures (ok:false, the backend keeps the rules-only result):
 *   - output not readable as JSON
 *   - an issue whose rule_id is not in allowed_rule_ids
 *   - suggested_text missing, empty, or longer than the limit
 *     (200 characters, 600 for category "additional")
 *   - suggested_text contains an obvious PHI pattern: date of birth, MRN or
 *     record number, SSN, phone number, email address
 *   - suggested_text mentions off-label use or pricing other than through
 *     the approved redirect phrases
 * Soft clean-ups:
 *   - an issue that repeats a rule the deterministic rules already found is
 *     dropped (the model is asked for ADDITIONAL issues only)
 *   - an issue whose excerpt is not in the note is dropped (not grounded)
 *   - duplicate issues are dropped; "why" is capped at 200 characters
 * ========================================================================== */
const ctx = $('Build Prompt').first().json;
const raw = $input.first().json || {};
const fail = (reason) => [{ json: { ok: false, reason: String(reason).slice(0, 200) } }];

/* The first complete {...} in the model text: tolerates code fences, prose and a
 * stray trailing brace (seen with Claude), which a strict parser rejects. */
function firstObject(s) {
  const start = s.indexOf('{');
  if (start < 0) return null;
  let depth = 0; let inStr = false; let esc = false;
  for (let i = start; i < s.length; i += 1) {
    const ch = s[i];
    if (inStr) { if (esc) esc = false; else if (ch === '\\') esc = true; else if (ch === '"') inStr = false; continue; }
    if (ch === '"') inStr = true;
    else if (ch === '{') depth += 1;
    else if (ch === '}') { depth -= 1; if (depth === 0) return s.slice(start, i + 1); }
  }
  return null;
}

function unwrap(value) {
  let v = value;
  for (let i = 0; i < 4; i += 1) {
    if (typeof v === 'string') {
      const s = v.replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim();
      try { v = JSON.parse(s); } catch (e) { const o = firstObject(s); if (!o) return null; try { v = JSON.parse(o); } catch (e2) { return null; } }
      continue;
    }
    if (v && typeof v === 'object' && !Array.isArray(v) && v.output !== undefined && Object.keys(v).length <= 2) { v = v.output; continue; }
    if (v && typeof v === 'object' && !Array.isArray(v) && v.text !== undefined && Object.keys(v).length === 1) { v = v.text; continue; }
    break;
  }
  return v && typeof v === 'object' && !Array.isArray(v) ? v : null;
}

const APPROVED_PHRASES = [
  'Off-label question sent to Medical Information',
  'Safety information reported to Pharmacovigilance',
  'Access questions referred to IncyteCARES',
];

function phiProblem(text) {
  const t = String(text);
  const thisYear = new Date().getFullYear();
  if (/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i.test(t)) return 'email address';
  if (/(\+?1[\s.-]?)?\(?\b\d{3}\)?[\s.-]\d{3}[\s.-]\d{4}\b/.test(t)) return 'phone number';
  if (/\b\d{3}-\d{2}-\d{4}\b/.test(t)) return 'social security number';
  if (/\b(MRN|medical record|record (number|no\.?|#)|chart (number|no\.?|#)|patient id)\b/i.test(t)) return 'medical record number';
  if (/\b(DOB|D\.O\.B\.?|date of birth|birth ?date|born (on|in))\b/i.test(t)) return 'date of birth';
  const dates = t.match(/\b\d{1,2}[\/.-]\d{1,2}[\/.-](\d{4})\b|\b(\d{4})-\d{2}-\d{2}\b/g) || [];
  for (const d of dates) {
    const y = parseInt((d.match(/\d{4}/) || ['0'])[0], 10);
    if (y && y < thisYear - 1) return 'date that looks like a date of birth';
  }
  return '';
}

function claimProblem(text) {
  let t = String(text);
  APPROVED_PHRASES.forEach((p) => { t = t.split(p).join(' '); });
  if (/off[\s-]?label/i.test(t)) return 'off-label wording outside the approved redirect';
  if (/\$\s?\d|\b\d+\s?(dollars|usd)\b|\b(coupon|discount|rebate|free (sample|samples|drug|product|trial))\b/i.test(t)) return 'pricing or incentive wording';
  return '';
}

try {
  if (raw.error) return fail('model_error: ' + (raw.error.message || raw.error));
  const out = unwrap(raw);
  if (!out) return fail('model output is not a JSON object');

  const allowed = new Set(ctx.allowed_rule_ids);
  const already = new Set(ctx.finding_rule_ids);
  const norm = (s) => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();
  const noteNorm = norm(ctx.note);

  const rawIssues = Array.isArray(out.issues) ? out.issues : [];
  const issues = [];
  const seen = new Set();
  for (const item of rawIssues) {
    if (!item || typeof item !== 'object') continue;
    const ruleId = String(item.rule_id || '').trim();
    if (!allowed.has(ruleId)) return fail('issue rule_id not in allowed_rule_ids: ' + (ruleId || '(empty)'));
    if (already.has(ruleId)) continue;
    const excerpt = String(item.excerpt || '').replace(/\s+/g, ' ').trim().slice(0, 160);
    if (!excerpt || noteNorm.indexOf(norm(excerpt)) < 0) continue;
    const key = ruleId + '|' + norm(excerpt);
    if (seen.has(key)) continue;
    seen.add(key);
    const why = String(item.why || '').replace(/\s+/g, ' ').trim().slice(0, 200);
    issues.push({ rule_id: ruleId, excerpt, why });
  }

  const suggested = String(out.suggested_text || '').replace(/[ \t]+/g, ' ').trim();
  if (!suggested) return fail('suggested_text missing');
  if (suggested.length > ctx.limit) return fail('suggested_text is ' + suggested.length + ' characters; limit is ' + ctx.limit);
  const phi = phiProblem(suggested);
  if (phi) return fail('suggested_text contains a possible ' + phi);
  const claim = claimProblem(suggested);
  if (claim) return fail('suggested_text contains ' + claim);

  return [{ json: { ok: true, issues, suggested_text: suggested } }];
} catch (e) {
  return fail('guard_error: ' + (e && e.message ? e.message : e));
}

/* MODEL FAILED
 * The LLM chain's error output: Azure OpenAI timed out, refused, or returned
 * something the Structured Output Parser could not read. Answer at once with
 * {ok:false, reason} so the backend falls back to the POC rules well inside
 * N8N_TIMEOUT_SECONDS instead of waiting for the execution to die. */
const e = $input.first().json || {};
const err = e.error;
const msg = (err && (err.message || err.description)) || (typeof err === 'string' ? err : '') || e.message || 'model call failed';
return [{ json: { ok: false, reason: 'model_error: ' + String(msg).replace(/\s+/g, ' ').slice(0, 180) } }];

/* REJECT REQUEST
 * The request broke the webhook contract (docs/ARCHITECTURE.md section 6).
 * Answer {ok:false, reason}; the backend falls back to the POC rules. */
const r = $input.first().json || {};
return [{ json: { ok: false, reason: 'invalid_request: ' + String(r.reason || 'unknown').slice(0, 180) } }];
